import subprocess, time, os, pathlib

def tmux_capture(cmds, cwd="/tmp/testrepo", width=80, height=24, env=None):
    subprocess.run(["tmux","kill-server"], capture_output=True)
    time.sleep(0.3)
    subprocess.run(["tmux","new-session","-d","-s","test","-x",str(width),"-y",str(height),"-c",cwd], check=True)
    if env:
        for k,v in env.items():
            subprocess.run(["tmux","setenv","-t","test",k,v], check=True)
    for c in cmds:
        if isinstance(c, str):
            subprocess.run(["tmux","send-keys","-t","test","-l",c], check=True)
            subprocess.run(["tmux","send-keys","-t","test","Enter"], check=True)
            time.sleep(1.2)
        else:
            typ, val = c
            if typ=="keys":
                if isinstance(val, list):
                    for k in val:
                        subprocess.run(["tmux","send-keys","-t","test",k], check=True)
                        time.sleep(0.4)
                else:
                    subprocess.run(["tmux","send-keys","-t","test",val], check=True)
                time.sleep(0.8)
            elif typ=="sleep":
                time.sleep(val)
            elif typ=="literal":
                subprocess.run(["tmux","send-keys","-t","test","-l",val], check=True)
                time.sleep(0.5)
    time.sleep(0.5)
    r=subprocess.run(["tmux","capture-pane","-t","test","-p"], capture_output=True, text=True)
    r2=subprocess.run(["tmux","capture-pane","-t","test","-p","-e"], capture_output=True, text=True)
    subprocess.run(["tmux","kill-server"], capture_output=True)
    return r.stdout, r2.stdout

