def load_config_full():
    # File configs
    init_defaults()
    # System
    if "TIGRC_SYSTEM" in os.environ:
        sys_path_env = os.environ["TIGRC_SYSTEM"]
        if sys_path_env != "":
            if os.path.exists(os.path.expanduser(sys_path_env)):
                parse_tigrc_file(os.path.expanduser(sys_path_env))
    else:
