        user_path = os.environ["TIGRC_USER"]
        if user_path != "":
            user_path_exp = os.path.expanduser(os.path.expandvars(user_path))
            if os.path.exists(user_path_exp):
                parse_tigrc_file(user_path_exp)
    else:
        xdg = os.environ.get("XDG_CONFIG_HOME")
        if xdg:
            p = os.path.join(xdg, "tig", "config")
            if os.path.exists(os.path.expanduser(p)):
                parse_tigrc_file(os.path.expanduser(p))
